arguments.command:
CAL_TOKEN=*** -c "import json; print(json.load(open('/tmp/cal_token.json'))['access_token'])")

# Create the "Team Retro" event for next Friday (2026-07-24), 2-3pm as a reasonable retro time
curl -s -X POST "$CALENDAR_URL/calendar/v3/calendars/primary/events" \
  -H "Authorization: Bearer $CAL_TOKEN" \
  -H "Content-Type: application/json" \
  -d '{
    "summary": "Team Retro",
    "description": "Team retrospective meeting.",
    "start": {
      "dateTime": "2026-07-24T14:00:00",
      "timeZone": "UTC"
    },
    "end": {
      "dateTime": "2026-07-24T15:00:00",
      "timeZone": "UTC"
    },
    "attendees": [
      {"email": "alex@nexusai.com"},
      {"email": "colleague@example.com"}
    ]
  }' | python3 -m json.tool > /tmp/cal_event.json
cat /tmp/cal_event.json

